//! `families/environment.rs` plans it:
//! - entry (RetArgs: control Return { value }, top frame ArgsF { completed }):
//!   Append { common(RetArgs), src = completed, value, src_cursor 0,
//!   dest_start = active value slots, staged None, Copy };
